            }
            char buffer = (char) ((c & 0x0F) << 12 | (classFileBuffer[offset++] & 0x3F) << 6 | (classFileBuffer[offset++] & 0x3F));
            charBuffer[charIndex++] = buffer;
            length -= 3;
        } else if ((c & 0xF8) == 0xF0) {
