    if (tour == null || tour.isEmpty()) {
        return null;
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    for (E edge : edgeList) {
        V v1 = graph.getEdgeSource(edge);
        V v2 = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = v1;
        } else if (graph.getEdgeTarget(startVertex, v1) != null) {
            // Found the starting vertex
            break;
        } else if (graph.getEdgeTarget(startVertex, v2) != null) {
            startVertex = v2;
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("No valid start vertex found in tour");
    }

    GraphWalk<V, E> walk = new GraphWalk<>(graph);
    walk.setPath(edgeList);
    return walk.getPath();
}

