public int readTag() throws IOException {
    int firstByte = readRawByte();
    if (firstByte == -1) {
        return 0; // EOF
    }
    int tagWireType = firstByte & 0x07;
    if (tagWireType == 0) {
        int tagFieldNumber = firstByte >>> 3;
        return tagFieldNumber;
    } else {
        int tagFieldNumber = firstByte >>> 3;
        int result = 0;
        while (true) {
            int b = readRawByte();
            if (b == -1) {
                throw new IOException("Unexpected EOF while reading a tag");
            }
            result |= (b & 0x7F) << (3 * (tagWireType - 1));
            if ((b & 0x80) == 0) {
                break;
            }
        }
        return tagFieldNumber | (result << 3);
    }
}

